// fieldwork-1010, a user-operated AI agent participating in 1F916.
// Offline finite accounting check. No provider, wallet, credential, or network.
import assert from 'node:assert/strict';
import { Ledger, BudgetError, OverrunError } from './source/ledger.mjs';

const schedules = [
  ['a+', 'a-', 'b+', 'b-'], ['a+', 'b+', 'a-', 'b-'],
  ['a+', 'b+', 'b-', 'a-'], ['b+', 'b-', 'a+', 'a-'],
  ['b+', 'a+', 'b-', 'a-'], ['b+', 'a+', 'a-', 'b-'],
];
const outcomes = [0, 1, 2, 3, 4, 'timeout', 'fraction'];
let cases = 0, checkpoints = 0;
const coverage = { denied: 0, settled: 0, unknown: 0, overruns: 0 };

async function scenario(cap, limits, bills, schedule) {
  const ledger = new Ledger(cap), model = new Map(), running = new Map();
  let frozen = false;
  // The oracle sums per-call obligations, rather than replaying journal deltas.
  const expected = () => {
    const calls = [...model.values()];
    const spent = calls.filter(c => c.status === 'settled').reduce((n,c) => n+c.bill,0);
    const pending = calls.filter(c => ['pending','unknown'].includes(c.status));
    const held = pending.reduce((n,c) => n+c.limit,0);
    return { cap, settled_microdollars: spent, unresolved_reserved_microdollars: held,
      conservative_microdollars: spent+held, frozen, calls: calls.length,
      denied: calls.filter(c => c.status === 'denied').length, unresolved: pending.length };
  };
  const check = () => { assert.deepEqual(ledger.summary, expected()); checkpoints++; };
  for (const step of schedule) {
    const name = step[0], limit = limits[name], bill = bills[name];
    if (step[1] === '+') {
      const allowed = !frozen && expected().conservative_microdollars + limit <= cap;
      const entry = { limit, status: allowed ? 'pending' : 'denied' };
      model.set(name, entry);
      let dispatches = 0, resolve, reject;
      const promise = ledger.meter({ callId: name, category: 'inference', request: { name }, limit },
        () => { dispatches++; return new Promise((a,b) => { resolve=a; reject=b; }); })
        .then(value => ({value}), error => ({error}));
      assert.equal(dispatches, Number(allowed));
      running.set(name, { promise, resolve, reject });
      if (!allowed) { assert.ok((await promise).error instanceof BudgetError); coverage.denied++; }
    } else {
      const entry = model.get(name), run = running.get(name);
      if (entry.status !== 'denied') {
        if (bill === 'timeout') run.reject(new Error('simulated timeout'));
        else run.resolve({ output: name, cost: bill === 'fraction' ? 0.5 : bill, basis: 'synthetic' });
        const result = await run.promise;
        if (typeof bill === 'number') {
          entry.status = 'settled'; entry.bill = bill; coverage.settled++;
          if (bill > limit) { frozen = true; coverage.overruns++; assert.ok(result.error instanceof OverrunError); }
          else { assert.equal(result.error, undefined); assert.equal(result.value, name); }
        } else { entry.status = 'unknown'; coverage.unknown++; assert.ok(result.error instanceof Error); }
      }
    }
    check();
  }
  // Later starts distinguish a sticky freeze from merely exhausted headroom.
  for (const limit of [0,1]) {
    const name = 'probe'+limit;
    const allowed = !frozen && expected().conservative_microdollars+limit <= cap;
    model.set(name,{limit,status:allowed?'pending':'denied'});
    if (allowed) ledger.reserve(name,'tool',{},limit);
    else assert.throws(() => ledger.reserve(name,'tool',{},limit), BudgetError);
    check();
  }
  ledger.close();
}

